import React, { FormEvent } from 'react';

import ArticleSelectInput from '@apps/Articles/components/ArticleSelectInput';
import { IHikingArticle } from '@apps/Hiking/@types/hikingArticles.types';
import { getInputDate } from '@helpers/dateHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import { showModal } from '@ui-kit/Modal';

interface IHikingArticleFormProps {
  hikingArticle: IHikingArticle;
  onSave: (t: IHikingArticle) => void;
}

const HikingArticleForm = ({ hikingArticle, onSave }: IHikingArticleFormProps) => {
  const [modelData, setModelData] = React.useState<IHikingArticle>(hikingArticle);
  const onSubmit = (e: FormEvent) => {
    e.preventDefault();
    onSave(modelData);
  };

  function handleChange<k extends keyof IHikingArticle>(fieldName: k) {
    return (value: IHikingArticle[k]) => setModelData({ ...modelData, [fieldName]: value });
  }

  return (
    <form onSubmit={onSubmit} className="d-flex flex-column" style={{ gap: 12, minWidth: '60vw' }}>
      <PohRow>
        <PohCol sm={2}>Статья</PohCol>
        <PohCol sm={10}>
          <ArticleSelectInput
            value={modelData.article}
            onChange={handleChange('article')}
            className="w-100 flex-grow-1"
            required
          />
        </PohCol>
      </PohRow>

      <PohInput
        horizontal
        type={InputTypes.textarea}
        label="Комментарий"
        value={modelData.comment}
        onChange={handleChange('comment')}
        placeholder=""
      />

      <PohRow>
        <PohCol sm={2}>Актуальность</PohCol>
        <PohCol sm={5} className="d-flex align-items-end">
          <PohInput
            horizontal
            label="С"
            type={InputTypes.datetimeLocal}
            value={modelData.actual_in ? getInputDate(modelData.actual_in) : ''}
            onChange={(v) => handleChange('actual_in')(v ? new Date(v) : null)}
          />
        </PohCol>
        <PohCol sm={5} className="d-flex align-items-end">
          <PohInput
            horizontal
            label="По"
            type={InputTypes.datetimeLocal}
            value={modelData.actual_out ? getInputDate(modelData.actual_out) : ''}
            onChange={(v) => handleChange('actual_out')(v ? new Date(v) : null)}
          />
        </PohCol>
      </PohRow>

      <PohRow>
        <PohCol sm={2} />
        <PohCol sm={10}>
          <PohButton type="submit" variant={ButtonVariant.Primary}>
            Сохранить
          </PohButton>
        </PohCol>
      </PohRow>
    </form>
  );
};

export const editHikingArticleInModal = (
  hikingArticle: IHikingArticle,
): Promise<IHikingArticle> => {
  return new Promise((res) => {
    showModal({
      title: hikingArticle.id > 0 ? 'Редактирование статьи похода' : 'Добавление статьи похода',
      children: (clos) => {
        return (
          <HikingArticleForm
            hikingArticle={hikingArticle}
            onSave={(up) => {
              res(up);
              clos();
            }}
          />
        );
      },
    });
  });
};
